     1→#!/usr/bin/env perl
     2→# ABOUTME: Validate Perl test files using Boolean semiring for fast syntax checking
     3→# ABOUTME: Demonstrates Boolean semiring's practical utility similar to `perl -c`
     4→use 5.42.0;
     5→use Test2::V0;
     6→use FindBin qw($RealBin);
     7→use File::Glob qw(bsd_glob);
     8→use Time::HiRes qw(time);
     9→
    10→local $| = 1;
    11→
    12→# Directory containing Perl test files
    13→my $test_dir = "$RealBin/../../perl-tests/t/base";
    14→
    15→unless (-d $test_dir) {
    16→    plan skip_all => "Perl test directory not found at $test_dir";
    17→}
    18→
    19→my @test_files = bsd_glob("$test_dir/*.t");
    20→
    21→unless (@test_files) {
    22→    plan skip_all => "No test files found in $test_dir";
    23→}
    24→
    25→diag "Validating " . scalar(@test_files) . " Perl test files using Boolean semiring";
    26→
    27→my $start_time = time();
    28→my $passed = 0;
    29→my $total = 0;
    30→
    31→for my $file (sort @test_files) {
    32→    my $name = $file =~ s{^.*/}{}r;
    33→    $total++;
    34→
    35→    # Use Boolean semiring for fast validation with 30s timeout
    36→    my $output;
    37→    my $exit_code;
    38→    my $timed_out = 0;
    39→
    40→    try {
    41→        local $SIG{ALRM} = sub { die "timeout\n" };
    42→        alarm 30;
    43→        $output = `$RealBin/../../app.pl --semiring Boolean '$file' 2>&1`;
    44→        $exit_code = $? >> 8;
    45→        alarm 0;
    46→    }
    47→    catch ($e) {
    48→        if ($e eq "timeout\n") {
    49→            $timed_out = 1;
    50→        }
    51→    }
    52→
    53→    # Check if validation was successful
    54→    my $success = (!$timed_out && $exit_code == 0 && $output =~ /Parse successful: 1/);
    55→
    56→    if ($success) {
    57→        pass "$name validates successfully with Boolean semiring";
    58→        $passed++;
    59→    } else {
    60→        fail "$name validates successfully with Boolean semiring";
    61→
    62→        # Provide diagnostic information
    63→        if ($timed_out) {
    64→            diag("  Validation timed out after 30 seconds for $file");
    65→        } elsif ($output =~ /PARSING STOPPED: Reached position (\d+) of (\d+)/) {
    66→            diag("  Failed to validate $file");
    67→            diag("  Stopped at position $1 of $2");
    68→        } elsif ($output =~ /Parse failed/) {
    69→            diag("  Parse failed for $file");
    70→        } else {
    71→            diag("  Unexpected output: $output");
    72→        }
    73→    }
    74→}
    75→
    76→my $elapsed = time() - $start_time;
    77→
    78→# Summary
    79→diag "";
    80→diag "=== Validation Summary ===";
    81→diag sprintf("Files validated: %d/%d (%.1f%%)", $passed, $total, 100 * $passed / $total);
    82→diag sprintf("Total time: %.3f seconds", $elapsed);
    83→diag sprintf("Average per file: %.3f seconds", $elapsed / $total) if $total > 0;
    84→
    85→done_testing;
    86→

