   268→        # Normal completion for regular items
   269→        for my $waiting_item (@waiting_for_lhs) {
   270→
   271→            my $waiting_element = $chart->get_element($waiting_item);
   272→            next unless $waiting_element;
   273→
   274→            # Semiring multiplication ⊗ combines sequential components
   275→            my $combined_element = $waiting_element * $completed_element;
   276→
   277→            my $new_item = Chalk::EarleyItem->new(
   278→                start_pos => $waiting_item->start_pos,
   279→                rule      => $waiting_item->rule,
   280→                dot_pos   => $waiting_item->dot_pos + 1,
   281→                end_pos   => $completed_item->end_pos
   282→            );
   283→
   284→            # Only add if not already in chart
   285→            unless ( $chart->has_item($new_item) ) {
   286→                $chart->add_element( $new_item, $combined_element );
   287→                push( @$agenda, $new_item );
   288→            }
   289→        }
   290→
   291→        # Handle Leo items waiting for this completion
   292→        for my $leo_item (@leo_waiting) {
   293→
   294→            # Unpack the Leo chain to get the original waiting item
   295→            my $current = $leo_item->top_item;
   296→            while ( $current isa Chalk::LeoItem ) {
   297→                $current = $current->top_item;
   298→            }
   299→
   300→            # Now $current is the original EarleyItem at the bottom of the chain
   301→            # Complete it with the current completed item
   302→            my $waiting_element = $chart->get_element($leo_item);
   303→            next unless $waiting_element;
   304→            my $combined_element = $waiting_element * $completed_element;
   305→
   306→            my $new_item = Chalk::EarleyItem->new(
   307→                start_pos => $current->start_pos,
   308→                rule      => $current->rule,
   309→                dot_pos   => $current->dot_pos + 1,
   310→                end_pos   => $completed_item->end_pos
   311→            );
   312→
   313→            # Only add if not already in chart
   314→            unless ( $chart->has_item($new_item) ) {
   315→                $chart->add_element( $new_item, $combined_element );
   316→                push( @$agenda, $new_item );
   317→            }
   318→        }
   319→    }
   320→
   321→    method predict( $item, $nonterminal, $chart, $agenda ) {
   322→        my $pos = $item->end_pos;
   323→
   324→# Check if we've already predicted this nonterminal from this rule at this position
   325→# Multiple rules can predict the same nonterminal, so we track by rule origin
   326→        return if $chart->has_predicted( $nonterminal, $pos, $item->rule->id );
   327→        $chart->mark_predicted( $nonterminal, $pos, $item->rule->id );
   328→
   329→        for my $rule ( $grammar->rules_for($nonterminal) ) {
   330→            my $predicted_item = Chalk::EarleyItem->new(
   331→                start_pos => $pos,
   332→                rule      => $rule,
   333→                dot_pos   => 0,
   334→                end_pos   => $pos
   335→            );
   336→
   337→            # Only add if not already in chart
   338→            unless ( $chart->has_item($predicted_item) ) {
   339→                my $rule_element = $semiring->init_element_from_rule($rule, $pos, $pos);
   340→                $chart->add_element( $predicted_item, $rule_element );
   341→                push( @$agenda, $predicted_item );
   342→            }
   343→        }
   344→
   345→        # Aycock-Horspool optimization: if the nonterminal is nullable,
   346→        # we can also advance the dot past it immediately
   347→        if ( $grammar->is_nullable($nonterminal) ) {
   348→            my $advanced_item = Chalk::EarleyItem->new(
   349→                start_pos => $item->start_pos,
   350→                rule      => $item->rule,
   351→                dot_pos   => $item->dot_pos + 1,
   352→                end_pos   => $item->end_pos
   353→            );
   354→
   355→            # Only add if not already present
   356→            unless ( $chart->has_item($advanced_item) ) {
   357→                my $current_element = $chart->get_element($item);
   358→                if ($current_element) {
   359→                    $chart->add_element( $advanced_item, $current_element );
   360→                    push( @$agenda, $advanced_item );
   361→                }
   362→            }
   363→        }
   364→    }
   365→
   366→    method scan( $item, $element, $chart, $pos, $match_length ) {
   367→        my $scanned_item = Chalk::EarleyItem->new(
   368→            start_pos => $item->start_pos,
   369→            rule      => $item->rule,
   370→            dot_pos   => $item->dot_pos + 1,
   371→            end_pos   => $pos + $match_length
   372→        );
   373→
   374→        # All semirings receive position updates during scan
   375→        # Semirings can choose to use or ignore positions based on their needs
   376→        my $scanned_element = $semiring->init_element_from_rule(
   377→            $item->rule,
   378→            $scanned_item->start_pos,
   379→            $scanned_item->end_pos
   380→        );
   381→
   382→        $chart->add_element( $scanned_item, $scanned_element );
   383→    }
   384→}
   385→
   386→1;
